from decimal import Decimal, InvalidOperation

_CENT = Decimal("0.01")


def _digits_int(d: Decimal) -> int:
    t = d.as_tuple()
    if not t.digits:
        return 0
    return int("".join(str(x) for x in t.digits))


def allocate_by_ratios(total: str, ratios: list) -> list[Decimal]:
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    # Strict "at most 2 decimal places" as written: check exponent.
    # Decimal(string) construction is exact, so exponent reflects written places.
    if amount.as_tuple().exponent < -2:
        raise ValueError("total must have at most 2 decimal places")
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError("ratios must be a non-empty list")
    weights: list[Decimal] = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError("bool weights are not accepted")
        if isinstance(entry, int):
            weight = Decimal(entry)
        elif isinstance(entry, Decimal):
            weight = entry
        elif isinstance(entry, str):
            try:
                weight = Decimal(entry)
            except (InvalidOperation, ValueError):
                raise ValueError(f"invalid weight: {entry!r}") from None
        else:
            raise ValueError(f"invalid weight: {entry!r}")
        if not weight.is_finite():
            raise ValueError("weights must be finite")
        if weight < 0:
            raise ValueError("weights must be >= 0")
        weights.append(weight)
    # Exact integer scaling of weights: W_i = weight_i * 10**scale.
    min_exp = min(w.as_tuple().exponent for w in weights)
    scale = -min_exp if min_exp < 0 else 0
    W: list[int] = []
    for w in weights:
        t = w.as_tuple()
        d_int = _digits_int(w)
        exp = t.exponent + scale
        # exp >= 0 by construction of scale
        val = d_int * (10 ** exp)
        if t.sign:
            val = -val
        W.append(val)
    total_W = sum(W)
    if total_W <= 0:
        raise ValueError("at least one weight must be > 0")
    negative = amount < 0
    # Exact cents from amount without context-limited arithmetic.
    abs_amount = amount.copy_abs()
    t_amt = abs_amount.as_tuple()
    cents = _digits_int(abs_amount) * (10 ** (t_amt.exponent + 2))
    # Exact shares: total_cents * W_i / total_W via integer divmod.
    floors: list[int] = []
    rems: list[int] = []
    for Wi in W:
        prod = cents * Wi
        fl = prod // total_W
        rm = prod % total_W
        floors.append(fl)
        rems.append(rm)
    remaining = cents - sum(floors)
    order = sorted(
        (i for i, w in enumerate(weights) if w > 0),
        key=lambda i: (-rems[i], -W[i], i),
    )
    for i in order[:remaining]:
        floors[i] += 1
    parts: list[Decimal] = []
    for fc in floors:
        part = Decimal(fc).scaleb(-2)
        # Ensure exponent is exactly -2 (Decimal(0).scaleb(-2) is 0.00).
        # scaleb already yields exponent -2 for integral fc.
        if negative and part != 0:
            part = -part
        parts.append(part)
    return parts

